import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.CBxkvBm_.js";const u=JSON.parse('{"title":"FEA (CalculiX, Abaqus & NASTRAN)","description":"","frontmatter":{},"headers":[],"relativePath":"languages/fea.md","filePath":"languages/fea.md"}'),c={name:"languages/fea.md"};function s(l,e,i,n,r,g){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="fea-calculix-abaqus-nastran" tabindex="-1">FEA (CalculiX, Abaqus &amp; NASTRAN) <a class="header-anchor" href="#fea-calculix-abaqus-nastran" aria-label="Permalink to &quot;FEA (CalculiX, Abaqus &amp; NASTRAN)&quot;">​</a></h1><p><code>@modelscript/fea</code> (<code>languages/fea</code>) provides native parsing, parametric template materialization, 3D CAD boundary condition synthesis, structural theory slicing, and cross-domain TGG synchronization for Finite Element Analysis input decks.</p><hr><h2 id="supported-dialects-extensions" tabindex="-1">Supported Dialects &amp; Extensions <a class="header-anchor" href="#supported-dialects-extensions" aria-label="Permalink to &quot;Supported Dialects &amp; Extensions&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Extension</th><th style="text-align:left;">Dialect</th><th style="text-align:left;">Key Directives</th></tr></thead><tbody><tr><td style="text-align:left;"><code>.inp</code></td><td style="text-align:left;">CalculiX / Abaqus input deck</td><td style="text-align:left;"><code>*HEADING</code>, <code>*NODE</code>, <code>*ELEMENT</code>, <code>*NSET</code>, <code>*ELSET</code>, <code>*MATERIAL</code>, <code>*ELASTIC</code>, <code>*DENSITY</code>, <code>*SOLID SECTION</code>, <code>*STEP</code>, <code>*STATIC</code>, <code>*FREQUENCY</code>, <code>*BOUNDARY</code>, <code>*CLOAD</code>, <code>*DLOAD</code></td></tr><tr><td style="text-align:left;"><code>.inpt</code></td><td style="text-align:left;">Parametric CalculiX / Abaqus template</td><td style="text-align:left;">Supports <code>{{ expression }}</code> mustache substitutions over workspace parameters</td></tr><tr><td style="text-align:left;"><code>.bdf</code></td><td style="text-align:left;">NASTRAN Bulk Data Deck</td><td style="text-align:left;"><code>SOL</code>, <code>CEND</code>, <code>BEGIN BULK</code>, <code>GRID</code>, <code>CTETRA</code>, <code>CHEXA</code>, <code>PSOLID</code>, <code>MAT1</code>, <code>SPC1</code>, <code>FORCE</code>, <code>MOMENT</code>, <code>LOAD</code>, <code>ENDDATA</code></td></tr><tr><td style="text-align:left;"><code>.fea</code></td><td style="text-align:left;">ModelScript native FEA configuration</td><td style="text-align:left;">Structured material, mesh, boundary, and load study definitions</td></tr></tbody></table><hr><h2 id="parametric-template-materialization-expr" tabindex="-1">Parametric Template Materialization (<code>{{ expr }}</code>) <a class="header-anchor" href="#parametric-template-materialization-expr" aria-label="Permalink to &quot;Parametric Template Materialization (&lt;code v-pre&gt;{{ expr }}&lt;/code&gt;)&quot;">​</a></h2><p>Input decks (<code>.inpt</code>, <code>.inp</code>, <code>.bdf</code>, <code>.fea</code>) can embed parametric expressions enclosed in <code>{{ ... }}</code> placeholders:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">*MATERIAL, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NAME</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=AL7075</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">*ELASTIC</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ E_modulus }}, {{ poisson_ratio }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">*DENSITY</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ rho_al }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">*CLOAD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LOAD_SET, 3, {{ -tip_mass * 9.81 }}</span></span></code></pre></div><p><code>materializeFeaDeck(templateText, parameters)</code> (<code>languages/fea/src/materializer.ts</code>) evaluates arithmetic expressions (<code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>, <code>^</code>), functions (<code>sin</code>, <code>cos</code>, <code>tan</code>, <code>sqrt</code>, <code>abs</code>, <code>min</code>, <code>max</code>, <code>log</code>, <code>exp</code>), and built-in constants (<code>PI</code>, <code>E</code>) via <code>evaluateFeaExpression</code>, formatting values in engineering notation and recording any unresolved symbols or syntax errors.</p><hr><h2 id="_3d-cad-face-boundary-condition-load-synthesis" tabindex="-1">3D CAD Face Boundary Condition &amp; Load Synthesis <a class="header-anchor" href="#_3d-cad-face-boundary-condition-load-synthesis" aria-label="Permalink to &quot;3D CAD Face Boundary Condition &amp; Load Synthesis&quot;">​</a></h2><p>When a user selects a topological face in the 3D CAD viewer, <code>synthesizeFeaBoundary</code> and <code>applyBoundaryActionToDeck</code> (<code>languages/fea/src/boundary-synthesizer.ts</code>) automatically generate solver-native boundary and load cards for the target dialect:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Boundary Kind</th><th style="text-align:left;">CalculiX / Abaqus (<code>.inp</code>)</th><th style="text-align:left;">NASTRAN Bulk Data (<code>.bdf</code>)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Fixed Support (<code>fixed</code>)</strong></td><td style="text-align:left;"><code>*BOUNDARY</code> constraining DOFs <code>1, 6</code> (or <code>1, 3</code>) on <code>NSET_&lt;FACE&gt;</code></td><td style="text-align:left;"><code>SPC1</code> card locking DOFs <code>123456</code> (or <code>123</code>) on <code>SET_&lt;FACE&gt;</code></td></tr><tr><td style="text-align:left;"><strong>Point / Concentrated Force (<code>force</code>)</strong></td><td style="text-align:left;"><code>*CLOAD</code> directional nodal force components $(F_x, F_y, F_z)$ along the face normal</td><td style="text-align:left;"><code>FORCE</code> card with magnitude and normal unit vector $(n_x, n_y, n_z)$</td></tr><tr><td style="text-align:left;"><strong>Distributed Pressure (<code>pressure</code>)</strong></td><td style="text-align:left;"><code>*DLOAD</code> surface pressure (<code>P</code>) applied to <code>ELSET_&lt;FACE&gt;</code></td><td style="text-align:left;"><code>PLOAD4</code> / <code>FORCE</code> cards distributed across face elements</td></tr><tr><td style="text-align:left;"><strong>Torque / Moment (<code>moment</code>)</strong></td><td style="text-align:left;"><code>*CLOAD</code> rotational DOFs <code>4, 5, 6</code></td><td style="text-align:left;"><code>MOMENT</code> card around face normal axis</td></tr></tbody></table><hr><h2 id="structural-theory-slicing-safety-margin-extraction" tabindex="-1">Structural Theory Slicing &amp; Safety Margin Extraction <a class="header-anchor" href="#structural-theory-slicing-safety-margin-extraction" aria-label="Permalink to &quot;Structural Theory Slicing &amp; Safety Margin Extraction&quot;">​</a></h2><p><code>extractFeaSlicingProperties(text)</code> (<code>languages/fea/src/language.ts</code>) extracts structural parameters (<code>DENSITY</code>, <code>VOLUME</code>, <code>MAX_VON_MISES_STRESS</code>, <code>YIELD_STRENGTH</code>) directly from the CST and evaluates the structural safety margin:</p><p>$$ \\text{Safety Factor (SF)} = \\frac{\\sigma_{\\text{yield}}}{\\sigma_{\\text{von Mises, max}}}, \\qquad \\text{isSafe} \\iff \\sigma_{\\text{von Mises, max}} \\le \\sigma_{\\text{yield}} $$</p><p>Returning <code>{ mass, maxVonMisesPa, yieldStrengthPa, safetyFactor, isSafe }</code> directly to the Multi-Domain Theory Coordinator (<code>CaeContractOracle</code>) and SysML v2 requirement verifiers.</p><hr><h2 id="built-in-solver-ide-actions" tabindex="-1">Built-In Solver &amp; IDE Actions <a class="header-anchor" href="#built-in-solver-ide-actions" aria-label="Permalink to &quot;Built-In Solver &amp; IDE Actions&quot;">​</a></h2><p><code>@modelscript/fea</code> registers three interactive actions in <code>feaLanguage.actions</code>:</p><ul><li><strong><code>open_fea_viewer</code></strong>: Opens the 3D FEA mesh, boundary condition, and von Mises stress contour viewer.</li><li><strong><code>materialize_deck</code></strong>: Evaluates all <code>{{ expr }}</code> template placeholders against workspace parameters to produce a concrete <code>.inp</code> or <code>.bdf</code> deck.</li><li><strong><code>run_simulation</code> (<code>fea_run_simulation</code>)</strong>: Parses <code>*MATERIAL</code>, <code>*ELASTIC</code>, <code>*BOUNDARY</code>, and <code>*CLOAD</code>/<code>*DLOAD</code> sections, solves the 3D tetrahedral finite element stiffness matrix, and returns nodal displacements and element von Mises stress contours.</li></ul><hr><h2 id="polyglot-tgg-rules" tabindex="-1">Polyglot TGG Rules <a class="header-anchor" href="#polyglot-tgg-rules" aria-label="Permalink to &quot;Polyglot TGG Rules&quot;">​</a></h2><p><code>@modelscript/fea</code> defines 6 bidirectional Triple Graph Grammar (TGG) rules in <code>languages/fea/src/language.ts</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Rule Name</th><th style="text-align:left;">Source (<code>fea</code>)</th><th style="text-align:left;">Target Language</th><th style="text-align:left;">Target Construct</th></tr></thead><tbody><tr><td style="text-align:left;"><code>FeaStressMassToModelicaParam</code></td><td style="text-align:left;"><code>FeaDeck</code> (<code>mass</code>, <code>maxVonMisesPa</code>)</td><td style="text-align:left;"><code>modelica</code></td><td style="text-align:left;"><code>ComponentClause</code> (<code>parameter Real</code>)</td></tr><tr><td style="text-align:left;"><code>FeaStressMassToSysmlAttribute</code></td><td style="text-align:left;"><code>FeaDeck</code> (<code>safetyFactor</code>, <code>mass</code>)</td><td style="text-align:left;"><code>sysml2</code></td><td style="text-align:left;"><code>AttributeUsage</code></td></tr><tr><td style="text-align:left;"><code>FeaMaterialToSysmlAttribute</code></td><td style="text-align:left;"><code>Section</code> (<code>*MATERIAL</code> / <code>MAT1</code>)</td><td style="text-align:left;"><code>sysml2</code></td><td style="text-align:left;"><code>AttributeUsage</code></td></tr><tr><td style="text-align:left;"><code>FeaBoundaryFixToModelicaFixed</code></td><td style="text-align:left;"><code>Section</code> (<code>*BOUNDARY</code> / <code>SPC1</code>)</td><td style="text-align:left;"><code>modelica</code></td><td style="text-align:left;"><code>ComponentClause</code> (<code>Modelica.Mechanics.MultiBody.Parts.Fixed</code>)</td></tr><tr><td style="text-align:left;"><code>FeaSpringToModelicaSpring</code></td><td style="text-align:left;"><code>Section</code> (<code>*SPRING</code>)</td><td style="text-align:left;"><code>modelica</code></td><td style="text-align:left;"><code>ComponentClause</code> (<code>Modelica.Mechanics.Translational.Components.Spring</code>)</td></tr><tr><td style="text-align:left;"><code>FeaLoadCaseToSysmlRequirement</code></td><td style="text-align:left;"><code>Section</code> (<code>*STEP</code> / <code>SUBCASE</code>)</td><td style="text-align:left;"><code>sysml2</code></td><td style="text-align:left;"><code>RequirementUsage</code></td></tr></tbody></table>`,27)])])}const h=t(c,[["render",s]]);export{u as __pageData,h as default};
